import React from "react";
import { render, screen } from "@testing-library/react";
import { composeStories } from "@storybook/react";
import { axe } from "jest-axe";
import ConsoleSpy from "../../lib/tests/ConsoleSpy";
import Button from "../Button";
import * as stories from "./ButtonGroup.stories";
import ButtonGroup from "./ButtonGroup";

const { Basic } = composeStories(stories) as any;

describe("ButtonGroup component", () => {
  ConsoleSpy();

  it("pass A11Y", async () => {
    const { container } = render(<Basic />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it("passes through props", () => {
    render(
      <ButtonGroup data-testid="buttongroup">
        <Button>One</Button>
      </ButtonGroup>
    );
    expect(screen.queryByRole("group")).toHaveAttribute("data-testid", "buttongroup");
  });
});
